/* ---------- helpers ---------- */
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money = v => v == null || v === "" ? "TBC" : "$" + Number(v).toFixed(2);
const bySort = (a, b) => (a.sort ?? 99) - (b.sort ?? 99) || String(a.name).localeCompare(b.name);
const slug = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 30) || "item";
const clone = o => JSON.parse(JSON.stringify(o));

/* the loaded catalogue; filled by DB.load() */
