const col = id => CAT.colours.find(c => c.id === id) || { id, name: id || "?", hex: "#999999" };
const sty = id => CAT.scenes.find(s => s.id === id) || { id, name: id || "" };
const prod = id => CAT.products.find(p => p.id === id) || { id, name: id || "Ornament", type: "bauble", price: null };

/* ---------- 3. DATA STORE: Firebase when configured, otherwise this browser (demo) ---------- */
const DB = (() => {
  const LS = "ellie_demo_db_v1";
  let fb = null, fs = null, auth = null;
  const mode = FIREBASE_CONFIG ? "firebase" : "demo";

  function demoRead(){
    try{ const v = JSON.parse(localStorage.getItem(LS)); if(v && v.settings) return v; }catch(e){}
    return { ...clone(DEFAULTS), orders: [] };
  }
  let mem = null;
  function demo(){ return (mem = demoRead()); }   // always re-read, so the shop and admin tabs stay in sync
  function demoSave(){ try{ localStorage.setItem(LS, JSON.stringify(mem)); }catch(e){} }
  function loadScript(src){ return new Promise((ok, bad) => { const s = document.createElement("script"); s.src = src; s.onload = ok; s.onerror = bad; document.head.appendChild(s); }); }

  async function initFirebase(){
    if(fb) return;
    const v = "10.12.2", base = `https://cdn.jsdelivr.net/npm/firebase@${v}/`;
    await loadScript(base + "firebase-app-compat.js");
    await loadScript(base + "firebase-firestore-compat.js");
    await loadScript(base + "firebase-auth-compat.js");
    fb = firebase.initializeApp(FIREBASE_CONFIG); fs = firebase.firestore(); auth = firebase.auth();
  }
  const listOf = async name => (await fs.collection(name).get()).docs.map(d => ({ ...d.data(), id: d.id }));
  function mergeSettings(s){ const d = clone(DEFAULTS.settings); return { ...d, ...s, promo: { ...d.promo, ...(s && s.promo) }, fontsOn: { ...d.fontsOn, ...(s && s.fontsOn) }, postage: { ...d.postage, ...(s && s.postage) }, pickup: { ...d.pickup, ...(s && s.pickup) } }; }

  return {
    mode,
    async load(){
      if(mode === "demo"){
        const d = demo();
        Object.assign(CAT, { settings: mergeSettings(d.settings), products: d.products, colours: d.colours, scenes: d.scenes });
      } else {
        await initFirebase();
        const sDoc = await fs.collection("config").doc("settings").get();
        const [products, colours, scenes] = await Promise.all([listOf("products"), listOf("colours"), listOf("scenes")]);
        Object.assign(CAT, {
          settings: mergeSettings(sDoc.exists ? sDoc.data() : {}),
          products: products.length ? products : clone(DEFAULTS.products),
          colours: colours.length ? colours : clone(DEFAULTS.colours),
          scenes: scenes.length ? scenes : clone(DEFAULTS.scenes)
        });
      }
      // new bauble designs (Nov 2026): the Name Bauble is back on, Pine & Bell is retired
      if(mode === "demo"){ try{ if(!localStorage.getItem("ellie_new_baubles_v1")){ CAT.products = CAT.products.filter(p => p.type !== "pinebell"); CAT.products.forEach(p => { if(p.type === "bauble"){ p.active = true; p.description = DEFAULTS.products[0].description; } }); localStorage.setItem("ellie_new_baubles_v1", "1"); demo().products = clone(CAT.products); demoSave(); } }catch(e){} }
      // Christmas Tree name ornament added (Nov 2026)
      if(mode === "demo"){ try{ if(!localStorage.getItem("ellie_tree_v1")){ if(!CAT.products.some(p => p.type === "tree")){ CAT.products.push(clone(DEFAULTS.products.find(p => p.id === "tree"))); CAT.products.forEach(p => { if(p.type === "family") p.sort = 5; }); } localStorage.setItem("ellie_tree_v1", "1"); demo().products = clone(CAT.products); demoSave(); } }catch(e){} }
      // new prices (Nov 2026): $8 ornaments, $10 family name tree, $3 flat postage, free over $50
      if(mode === "demo"){ try{ if(!localStorage.getItem("ellie_prices_v2")){ CAT.products.forEach(p => { if(["bauble","disc","star","tree"].includes(p.type)) p.price = 8; if(p.type === "family") p.price = 10; }); CAT.settings.postage = { ...CAT.settings.postage, flat: 3, freeOver: 50 }; localStorage.setItem("ellie_prices_v2", "1"); const m = demo(); m.products = clone(CAT.products); m.settings = { ...(m.settings || {}), postage: clone(CAT.settings.postage) }; demoSave(); } }catch(e){} }
      if(mode === "demo"){ try{ if(!localStorage.getItem("ellie_snowfall_v1")){ CAT.scenes = clone(DEFAULTS.scenes); localStorage.setItem("ellie_snowfall_v1", "1"); demo().scenes = clone(CAT.scenes); demoSave(); } }catch(e){} }
      CAT.scenes.forEach(s => { if(s.id === "vine" && s.name === "Berry Vine") s.name = "Vine Wreath"; });
      // scenes the print file no longer has are dropped; the old "Snowflakes" is now the big "Snowflake"
      const known = DEFAULTS.scenes.map(s => s.id);
      CAT.scenes = CAT.scenes.filter(s => known.includes(s.id)).map(s => s.id === "snow" && s.name === "Snowflakes" ? { ...s, name: "Snowflake" } : s);
      DEFAULTS.scenes.forEach(d => { if(!CAT.scenes.find(s => s.id === d.id)) CAT.scenes.push(clone(d)); });
      CAT.products.sort(bySort); CAT.colours.sort(bySort); CAT.scenes.sort(bySort);
      return CAT;
    },
    async saveSettings(s){
      CAT.settings = s;
      if(mode === "demo"){ demo().settings = clone(s); demoSave(); return; }
      await fs.collection("config").doc("settings").set(s);
    },
    async saveItem(kind, item){            // kind: products | colours | scenes
      const list = CAT[kind], i = list.findIndex(x => x.id === item.id);
      if(i >= 0) list[i] = item; else list.push(item);
      list.sort(bySort);
      if(mode === "demo"){ demo()[kind] = clone(list); demoSave(); return; }
      const { id, ...data } = item; await fs.collection(kind).doc(id).set(data);
    },
    async deleteItem(kind, id){
      CAT[kind] = CAT[kind].filter(x => x.id !== id);
      if(mode === "demo"){ demo()[kind] = clone(CAT[kind]); demoSave(); return; }
      await fs.collection(kind).doc(id).delete();
    },
    async seedIfEmpty(){                    // first admin login on Firebase: copy the starting catalogue up
      if(mode === "demo") return false;
      const p = await fs.collection("products").limit(1).get();
      if(!p.empty) return false;
      const b = fs.batch();
      b.set(fs.collection("config").doc("settings"), CAT.settings);
      for(const k of ["products","colours","scenes"]) CAT[k].forEach(({ id, ...d }) => b.set(fs.collection(k).doc(id), d));
      await b.commit(); return true;
    },
    async createOrder(order){
      if(mode === "demo"){ demo().orders.push(clone(order)); demoSave(); return; }
      const { id, ...data } = order; await fs.collection("orders").doc(id).set(data);
    },
    async listOrders(){
      const list = mode === "demo" ? clone(demo().orders) : await listOf("orders");
      return list.sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
    },
    async updateOrder(id, patch){
      if(mode === "demo"){ const o = demo().orders.find(x => x.id === id); if(o) Object.assign(o, patch); demoSave(); return; }
      await fs.collection("orders").doc(id).update(patch);
    },
    async deleteOrder(id){
      if(mode === "demo"){ demo().orders = demo().orders.filter(x => x.id !== id); demoSave(); return; }
      await fs.collection("orders").doc(id).delete();
    },
    // admin sign-in
    async onAuth(cb){
      if(mode === "demo"){ cb({ email: "demo mode" }); return; }
      await initFirebase(); auth.onAuthStateChanged(u => cb(u));
    },
    async login(email, pass){ await initFirebase(); return auth.signInWithEmailAndPassword(email, pass); },
    async logout(){ if(auth) await auth.signOut(); },
    async resetDemo(){ if(mode === "demo"){ mem = { ...clone(DEFAULTS), orders: [] }; demoSave(); } }
  };
})();

/* ---------- pricing ---------- */
// units = list of unit prices (null = price TBC). The promo makes the cheapest ones free.
function priceFor(units){
  const qty = units.length, pr = CAT.settings.promo;
  const on = pr && pr.enabled && pr.buy > 0 && pr.free > 0;
  const free = on ? Math.floor(qty / (pr.buy + pr.free)) * pr.free : 0;
  const unknown = units.some(u => u == null || u === "");
  const full = unknown ? null : units.reduce((s, u) => s + Number(u), 0);
  const discount = unknown ? null : [...units].map(Number).sort((a, b) => a - b).slice(0, free).reduce((s, u) => s + u, 0);
  const sub = unknown ? null : full - discount;
  const toNext = on ? (pr.buy + pr.free) - (qty % (pr.buy + pr.free)) : null;
  return { qty, free, full, discount, sub, toNext };
}
const itemType = i => i.type || prod(i.productId).type;
function itemDesc(i){
  const t = itemType(i);
  return (i.productName || prod(i.productId).name) + (t === "bauble" && i.style ? " · " + (i.styleName || sty(i.style).name) : "") + (t !== "family" && t !== "photo" ? " · " + (i.fontName || NAME_FONTS[fontKey(i)].label) + " font" : "") + (i.year ? " · " + i.year : " · no year");
}
function itemTitle(i){ return itemType(i) === "family" ? (i.names || []).join(", ") : i.name; }
function itemColours(i){ return `${i.baseName || col(i.base).name} / ${i.textName || col(i.text).name}`; }

/* ---------- 4. ORNAMENT DRAWINGS (match the print files) ---------- */

function photoSVG(o){
  const p = prod(o.productId), txt = col(o.text).hex, base = col(o.base).hex;
  const name = (o.name || "").trim() || "Your name", img = o.image || p.image || "";
  const fs = Math.min(13, 80 / Math.max(name.length, 1));
  return `<svg viewBox="-46 -46 92 92" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(name)}">
    <defs><clipPath id="ph${++uid}"><rect x="-44" y="-44" width="88" height="88" rx="12"/></clipPath></defs>
    <rect x="-44" y="-44" width="88" height="88" rx="12" fill="${base}"/>
    ${img ? `<image href="${img}" x="-44" y="-44" width="88" height="88" preserveAspectRatio="xMidYMid slice" clip-path="url(#ph${uid})"/>` : ""}
    <rect x="-40" y="20" width="80" height="20" rx="10" fill="${base}" opacity=".92"/>
    <text x="0" y="${34 - (13 - fs) * 0.3}" text-anchor="middle" font-family="'Dancing Script', cursive" font-weight="700" font-size="${fs.toFixed(1)}" fill="${txt}" data-fit="74">${esc(name)}</text>
  </svg>`;
}
let uid = 0;
function polar(r, a){ a = a*Math.PI/180; return [r*Math.cos(a), -r*Math.sin(a)]; }
function star(cx, cy, r){
  let p = [];
  for(let i=0;i<10;i++){ const rr = i%2 ? r*.45 : r, a = (90+i*36)*Math.PI/180; p.push((cx+rr*Math.cos(a)).toFixed(2)+","+(cy-rr*Math.sin(a)).toFixed(2)); }
  return `<polygon points="${p.join(" ")}"/>`;
}
function tree(x, base, h){
  const w = h*.62; let s = `<rect x="${x-.9}" y="${base-h*.2}" width="1.8" height="${h*.2+1}"/>`;
  for(let i=0;i<3;i++){
    const y0 = base - h*(.15+i*.25), ww = w*(1-i*.25);
    s += `<polygon points="${x-ww/2},${y0} ${x+ww/2},${y0} ${x},${y0-h*.42}"/>`;
  }
  return s;
}
function holly(cy){
  return `<g transform="translate(0 ${cy})">
    <ellipse cx="-6" cy="3" rx="6.5" ry="2.8" transform="rotate(-25 -6 3)"/>
    <ellipse cx="6" cy="3" rx="6.5" ry="2.8" transform="rotate(25 6 3)"/>
    <circle cx="-1.8" cy="2.4" r="2"/><circle cx="1.8" cy="2.4" r="2"/><circle cx="0" cy="5" r="2"/></g>`;
}
function snowflake(cx, cy, r){
  let s = `<g transform="translate(${cx} ${cy})" stroke-width="1.3" stroke-linecap="round" fill="none">`;
  for(let i=0;i<6;i++){
    s += `<g transform="rotate(${i*60})"><line x1="0" y1="0" x2="0" y2="${-r}"/><line x1="0" y1="${-r*.55}" x2="${r*.3}" y2="${-r*.8}"/><line x1="0" y1="${-r*.55}" x2="${-r*.3}" y2="${-r*.8}"/></g>`;
  }
  return s + `</g>`;
}

