const defaultFont = type => type === "tree" ? "modern" : "script";
const fontKey = o => NAME_FONTS[o && o.font] ? o.font : defaultFont(o && o.type);
const fontsOn = () => Object.keys(NAME_FONTS).filter(k => !(CAT.settings && CAT.settings.fontsOn && CAT.settings.fontsOn[k] === false));
// the name as printed (capitals for Modern) and the measured box around its letters at size t
function nameMetrics(name, fk){
  const nf = NAME_FONTS[fk] || NAME_FONTS.script, f = FONT_FIT[nf.font];
  const text = nf.caps ? String(name).toUpperCase() : String(name);
  const adv = [...text].reduce((s, c) => s + (f.adv[c] ?? f.wide), 0);
  const B = FONT_BEAR[nf.font] || {}, ch = [...text], lsb = ch.length ? (B[ch[0]] || [0,0])[0] : 0, rsb = ch.length ? (B[ch[ch.length-1]] || [0,0])[1] : 0;
  return { nf, f, text, adv, left: t => f.C*adv*t/2 + f.DL*t, right: t => f.C*adv*t/2 + f.DR*t, top: t => f.top*t, bot: t => f.bot*t,
           inkW: t => f.K*t*(adv - lsb - rsb), inkDx: t => f.K*t*(lsb - rsb)/2 };
}
function nameText(o, x, y, size, fill){
  const m = nameMetrics((o.name || "").trim() || "Your name", fontKey(o));
  return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central" font-family="${m.nf.css}" font-weight="${m.nf.weight}"
      font-size="${size.toFixed(2)}" fill="${fill}" data-center="${x},${y}">${esc(m.text)}</text>`;
}
