// where the name goes on each design: [centre x, centre y (y up), max size, max width] - same as bauble.scad
const BAUBLE_NAME = { vine: [0, 0, 15, 64, 30.5], snowfall: [0, 0.5, 15, 70, 37, -9.05, 9.1], holly_fern: [0, 2, 16, 70], bow_tree: [8, 3, 16, 50], starry: [0, 4, 19, 66], holly_stripe: [0, -7, 14, 68] };
function baubleFit(name, design, yr, fk){
  const N = BAUBLE_NAME[design] || BAUBLE_NAME.snowfall, m = nameMetrics(name, fk || "script");
  const cx = N[0], RI = N[4] ?? 37, band = N.length > 6, topk = m.nf.caps ? m.f.top : 0.8*m.f.top;
  const below = t => yr ? 0.55*t + 1.2 + 4 : m.bot(t);
  const cyAt = t => band ? (N[5] + N[6])/2 + (below(t) - m.top(t))/2 : N[1] + (yr ? 2.5 : 0);
  const fits = t => { const cy = cyAt(t), y = Math.abs(cy) + topk*t, chord = 2*Math.sqrt(Math.max(0, (RI-1.5)**2 - y*y));
    return (!band || m.top(t) + below(t) <= N[6] - N[5]) && 2*Math.max(m.left(t), m.right(t)) <= Math.min(N[3], chord - 2*Math.abs(cx)); };
  const max = N[2]*m.nf.scale;
  let t = max; if(!fits(t)){ let lo = 3, hi = t; for(let i=0;i<10;i++){ const mm = (lo+hi)/2; if(fits(mm)) lo = mm; else hi = mm; } t = lo; }
  return { t, ok: fits(t), cx, cy: cyAt(t), adv: m.adv, C: m.f.C, K: m.f.K };
}
function baubleLayout(o){ return { yr: !!o.year }; }
function ornamentSVG(o){
  const design = BAUBLE_ART[o.style] ? o.style : "snowfall", art = BAUBLE_ART[design];
  const base = col(o.base).hex, top = col(o.text).hex, name = (o.name || "").trim() || "Your name";
  const r = baubleFit(name, design, !!o.year, fontKey(o));
  const light = ["white","natural","gold"].includes(o.base);
  return `<svg viewBox="-50 -62 100 112" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(name)} bauble">
    <path fill="${base}" fill-rule="evenodd" d="${art.base2d}" ${light ? 'stroke="rgba(86,63,45,.35)" stroke-width=".35"' : ""}/>
    <path fill="${top}" fill-rule="evenodd" d="${art.deco2d}"/>
    ${nameText(o, r.cx, (-r.cy).toFixed(2), r.t*r.K, top)}
    ${o.year ? `<text x="${(r.cx + r.C*r.adv*r.t*0.24).toFixed(2)}" y="${(-(r.cy - 0.55*r.t - 1.2 - 4)).toFixed(2)}" text-anchor="middle"
      font-family="'Archivo Black', 'Arial Black', sans-serif" font-size="5.56" letter-spacing=".4" fill="${top}">${esc(o.year)}</text>` : ""}
  </svg>`;
}

