// Same fit check as the print files: the name (and year) are shrunk until every part sits inside the shape with a safety margin.
function fitText(name, year, opt){
  const m = nameMetrics(name, opt.font || "script"), f = m.f;
  const adv = m.adv;
  const bold = 0.2 * opt.s, gap = 1.0 * opt.s, ys = opt.yearSize;
  const nameBox = t => [-(m.inkW(t)/2 + bold + 0.4*opt.s), m.inkW(t)/2 + bold + 0.4*opt.s, -(m.top(t) + bold), m.bot(t) + bold]; // SVG y points down; centred on the letters
  const yearX = t => f.C * adv * t * 0.24;
  const yearBase = t => t*0.5 + gap + ys;
  const yearBox = t => { const yw = 0.96 * ys * year.length / 4; return [yearX(t) - yw/2, yearX(t) + yw/2, yearBase(t) - ys, yearBase(t) + 0.1]; };
  const pts = (b, n = 24) => { const o = []; for(let i=0;i<=n;i++){ const x = b[0]+(b[1]-b[0])*i/n, y = b[2]+(b[3]-b[2])*i/n; o.push([x,b[2]],[x,b[3]],[b[0],y],[b[1],y]); } return o; };
  const fits = t => [...pts(nameBox(t)), ...(year ? pts(yearBox(t)) : [])].every(opt.clear);
  let t = opt.maxSize * m.nf.scale;
  while(t > 3 && !fits(t)) t -= 0.1;
  return { t, ok: fits(t), yearX: yearX(t), yearBase: yearBase(t), K: f.K, dx: -m.inkDx(t) };
}
function nameAndYear(name, year, txt, opt){
  const r = fitText(name, year, opt);
  return `${nameText({ name, font: opt.font }, r.dx.toFixed(2), 0, r.t * r.K, txt)}
    ${year ? `<text x="${r.yearX.toFixed(2)}" y="${r.yearBase.toFixed(2)}" text-anchor="middle" font-family="'Archivo Black', 'Arial Black', sans-serif" font-size="${(opt.yearSize / 0.72).toFixed(2)}"
      letter-spacing=".5" fill="${txt}">${esc(year)}</text>` : ""}`;
}
// does this name (and year) fit on a disc / star? (false = too long even at the smallest size)
function nameFits(type, name, year, style, font){
  font = NAME_FONTS[font] ? font : defaultFont(type);
  if(type === "bauble") return baubleFit(name, style, !!year, font).ok;
  if(type === "tree") return treeFit(name, font).ok;
  if(type === "disc") return fitText(name, year, { maxSize: 17 * DISC_K, yearSize: 4.8 * DISC_K, s: 1, clear: discClear, font }).ok;
  if(type === "star") return fitText(name, year, { maxSize: 13 * (94/90) * STAR_S, yearSize: 4.4 * (94/90) * STAR_S, s: STAR_S, clear: starClear, font }).ok;
  return true;
}
